// ADR-0008 Decision 1 -- structural (contract-shape) validation only. This
// checks the request matches the Finance Inbox Request Contract; it is NOT
// Finance-specific validation (no amount/category/date rules -- those never
// appear in the Request contract at all, and belong to a Handler if they
// ever did).
const req = $json || {};

const KNOWN_CHANNELS = ['slack', 'telegram', 'whatsapp', 'retell', 'web-chat', 'ocr'];
const reasons = [];

function requireNonEmptyString(field) {
  if (typeof req[field] !== 'string' || req[field].trim().length === 0) {
    reasons.push(`Missing/empty required field: ${field}.`);
  }
}

requireNonEmptyString('contractVersion');
requireNonEmptyString('workflowExecutionId');
requireNonEmptyString('workflowName');
requireNonEmptyString('channel');

if (typeof req.rawText !== 'string') {
  reasons.push('rawText must be a string (may be empty).');
}

if (typeof req.channel === 'string' && !KNOWN_CHANNELS.includes(req.channel)) {
  reasons.push(`Unknown channel: ${req.channel}.`);
}

if (!('externalUserId' in req)) reasons.push('Missing externalUserId key.');
if (!('externalMessageId' in req)) reasons.push('Missing externalMessageId key.');
if (!Array.isArray(req.attachments)) reasons.push('attachments must be an array.');

return [{
  json: {
    valid: reasons.length === 0,
    reason: reasons.join(' '),
    contractVersion: req.contractVersion,
    workflowExecutionId: req.workflowExecutionId,
    workflowName: req.workflowName,
    channel: req.channel,
    externalUserId: req.externalUserId ?? null,
    externalMessageId: req.externalMessageId ?? null,
    rawText: typeof req.rawText === 'string' ? req.rawText : '',
    attachments: Array.isArray(req.attachments) ? req.attachments : [],
  },
}];

// The request never reached the AI Agent -- this is an orchestration-layer
// rejection (malformed envelope), not a Finance business decision, so it
// still returns a fully Response-contract-shaped object (ADR-0008 Decision 2).
const v = $json;

return [{
  json: {
    contractVersion: '1',
    workflowExecutionId: v.workflowExecutionId || 'unknown',
    status: 'error',
    intent: 'UNRECOGNIZED',
    message: 'This request does not match the Finance Inbox Workflow Contract and could not be processed.',
    data: null,
    clarifyingQuestion: null,
  },
}];

// ADR-0008 Decision 4 -- a malformed/unparseable Agent response, an intent
// outside the known catalog, or the Agent call failing outright (e.g. a
// local Ollama model returning output that doesn't fit the required
// schema -- a real, observed failure mode, not hypothetical; see ADR-0007's
// own account of local-model JSON-schema unreliability, and
// "AI Agent - Classify Intent"'s onError: continueRegularOutput) is forced
// to UNRECOGNIZED rather than reaching the Intent Router with a bad value
// or crashing this workflow. Original request context is read back from
// "Validate Request Contract" by node name, not trusted to have survived
// through the Agent node -- the Agent's own output shape is whatever the
// Structured Output Parser produced (or an error object), nothing more.
const context = $('Validate Request Contract').item.json;
const KNOWN_INTENTS = [
  'CREATE_EXPENSE', 'GET_BUDGET', 'GET_DASHBOARD', 'GET_FINANCE_QUESTION',
  'CREATE_INCOME', 'CREATE_TRANSFER', 'UPLOAD_RECEIPT', 'UNRECOGNIZED',
];

let classification = null;
if ($json && $json.error) {
  const message = String(($json.error && $json.error.message) || $json.error);
  console.log(`[Validate Agent Output] AI Agent call failed, defaulting to UNRECOGNIZED: ${message}`);
} else {
  try {
    const raw = $json.output;
    classification = typeof raw === 'string' ? JSON.parse(raw) : raw;
  } catch (error) {
    classification = null;
  }
}

const intent = classification && KNOWN_INTENTS.includes(classification.intent)
  ? classification.intent
  : 'UNRECOGNIZED';
const confidence = classification && typeof classification.confidence === 'number'
  ? classification.confidence
  : 0;

return [{
  json: {
    contractVersion: context.contractVersion,
    workflowExecutionId: context.workflowExecutionId,
    workflowName: context.workflowName,
    channel: context.channel,
    externalUserId: context.externalUserId,
    externalMessageId: context.externalMessageId,
    rawText: context.rawText,
    attachments: context.attachments,
    intent,
    confidence,
  },
}];

// Orchestration-layer only: if the Execute Workflow call itself failed --
// today, ALWAYS, since no Handler workflow exists yet (Phase 2 explicitly
// does not build one) -- this synthesizes a Response-contract-shaped
// fallback (ADR-0008 Decision 2), using context preserved from "Validate
// Agent Output" since a failed Execute Workflow call loses the original
// request. This is infrastructural resilience ("the handler is
// unreachable"), never a Finance business decision -- no amount/category/
// budget logic appears here. On success, the Handler's own response is
// returned completely unchanged, per this workflow's stated scope.
const context = $('Validate Agent Output').item.json;
const handlerResult = $json;

if (handlerResult && handlerResult.error) {
  const message = String((handlerResult.error && handlerResult.error.message) || handlerResult.error);
  console.log(`[Return Handler Response] Handler call failed for intent ${context.intent}: ${message}`);

  return [{
    json: {
      contractVersion: '1',
      workflowExecutionId: context.workflowExecutionId,
      status: 'error',
      intent: context.intent,
      message: "Sorry, I couldn't process that just now. Please try again in a moment.",
      data: null,
      clarifyingQuestion: null,
    },
  }];
}

return [{ json: handlerResult }];
